def test_nested_round_trip(run, x):
    import base64
    import json
    import zlib
    def same(actual, expected):
        if type(actual) is not type(expected):
            return False
        if isinstance(expected, dict):
            return set(actual) == set(expected) and all(same(actual[key], expected[key]) for key in expected)
        if isinstance(expected, list):
            return len(actual) == len(expected) and all(same(a, b) for a, b in zip(actual, expected))
        return actual == expected
    answer = run(x)
    try:
        value = json.loads(zlib.decompress(base64.b64decode(answer, validate=True)))
        ok = same(value, x['data_dict'])
    except Exception:
        ok = False
    assert ok

